package nl.dwmarketing.callerid;
import android.content.Context;import android.security.keystore.*;import android.util.Base64;
import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.*;import java.nio.file.*;import org.json.*;
final class PrivateStore {
 private static KeyStore store()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);return ks;}
 private static synchronized javax.crypto.SecretKey aes()throws Exception{KeyStore ks=store();if(!ks.containsAlias("dw-data")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("dw-data",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (javax.crypto.SecretKey)ks.getKey("dw-data",null);}
 static synchronized void put(Context c,String name,JSONObject value)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,aes());JSONObject envelope=new JSONObject().put("iv",Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)).put("data",Base64.encodeToString(cipher.doFinal(value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)),Base64.NO_WRAP));Path target=c.getFilesDir().toPath().resolve(name),tmp=c.getFilesDir().toPath().resolve(name+".tmp");Files.write(tmp,envelope.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING);}
 static synchronized JSONObject get(Context c,String name)throws Exception{Path p=c.getFilesDir().toPath().resolve(name);if(!Files.exists(p))return null;if(Files.size(p)>10000000)throw new Exception("Te groot");JSONObject envelope=new JSONObject(new String(Files.readAllBytes(p),java.nio.charset.StandardCharsets.UTF_8));Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,aes(),new GCMParameterSpec(128,Base64.decode(envelope.getString("iv"),Base64.NO_WRAP)));return new JSONObject(new String(cipher.doFinal(Base64.decode(envelope.getString("data"),Base64.NO_WRAP)),java.nio.charset.StandardCharsets.UTF_8));}
 static synchronized void clear(Context c){c.deleteFile("session");c.deleteFile("snapshot");c.deleteFile("session.tmp");c.deleteFile("snapshot.tmp");}
 private static synchronized KeyStore keys()throws Exception{KeyStore ks=store();if(!ks.containsAlias("dw-device")){KeyPairGenerator g=KeyPairGenerator.getInstance("RSA","AndroidKeyStore");g.initialize(new KeyGenParameterSpec.Builder("dw-device",KeyProperties.PURPOSE_SIGN|KeyProperties.PURPOSE_VERIFY).setKeySize(2048).setDigests(KeyProperties.DIGEST_SHA256).setSignaturePaddings(KeyProperties.SIGNATURE_PADDING_RSA_PKCS1).build());g.generateKeyPair();}return store();}
 static String publicKey()throws Exception{return Base64.encodeToString(keys().getCertificate("dw-device").getPublicKey().getEncoded(),Base64.NO_WRAP);}
 static String sign(String message)throws Exception{Signature s=Signature.getInstance("SHA256withRSA");s.initSign((PrivateKey)keys().getKey("dw-device",null));s.update(message.getBytes(java.nio.charset.StandardCharsets.UTF_8));return Base64.encodeToString(s.sign(),Base64.NO_WRAP);}
}
